<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    add_compile_options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(-fsanitize=thread -g -O1)</span></span>
